<style type="text/css">
    .video-section {
        padding: 80px 0;
        background: #f8faf8;
    }

    .container {
        width: min(1100px, 92%);
        margin: 0 auto;
    }

    .section-title {
        text-align: center;
        margin-bottom: 40px;
    }

    .section-title span {
        color: #16834a;
        font-size: 14px;
        font-weight: 700;
        letter-spacing: 2px;
    }

    .section-title h2 {
        margin: 10px 0;
        font-size: 40px;
        color: #173b29;
    }

    .section-title p {
        max-width: 650px;
        margin: 0 auto;
        color: #666;
        font-size: 16px;
    }

    .video-wrapper {
        width: 500px;
        max-width: 100%;
        aspect-ratio: 9 / 16;

        margin: 0 auto;

        overflow: hidden;
        border-radius: 20px;

        background: #000;

        box-shadow: 0 20px 50px rgba(0, 0, 0, 0.18);
    }

    .video-wrapper iframe {
        width: 100%;
        height: 100%;
        display: block;
        border: 0;
    }

    /* YouTube is loaded only when the visitor requests the video.
       This removes the heavy third-party iframe from the initial page load. */
    .video-lazy {
        position: relative;
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        background: #000;
    }

    .video-play-button {
        width: 72px;
        height: 72px;
        border: 0;
        border-radius: 50%;
        background: #ff0000;
        color: #fff;
        display: flex;
        align-items: center;
        justify-content: center;
        cursor: pointer;
        box-shadow: 0 8px 25px rgba(0,0,0,.25);
    }

    .video-play-button span {
        font-size: 28px;
        line-height: 1;
        margin-left: 4px;
    }

    .video-lazy iframe {
        width: 100%;
        height: 100%;
        border: 0;
        display: block;
    }
    @media (max-width: 600px) {

        .video-section {
            padding: 50px 0;
        }

        .section-title h2 {
            font-size: 28px;
        }

        .section-title p {
            font-size: 14px;
        }

        .video-wrapper {
            width: 100%;
            max-width: 340px;
            border-radius: 14px;
            min-height: 530px;
        }
    }
</style>
