<script>
document.addEventListener("DOMContentLoaded", function () {

    // ================================
    // PRODUCT INFORMATION
    // ================================

    const unitPrice = 900;

    let quantity = 1;


    // ================================
    // ELEMENTS
    // ================================

    const minusBtn =
        document.getElementById("minusBtn");

    const plusBtn =
        document.getElementById("plusBtn");

    const quantityInput =
        document.getElementById("quantity");

    const summaryQuantity =
        document.getElementById("summaryQuantity");

    const summaryUnitPrice =
        document.getElementById("summaryUnitPrice");

    const subtotal =
        document.getElementById("subtotal");

    const total =
        document.getElementById("total");


    // Form fields

    const nameInput =
        document.getElementById("name");

    const phoneInput =
        document.getElementById("phone");

    const addressInput =
        document.getElementById("address");

    const placeOrderBtn =
        document.getElementById("placeOrderBtn");


    // ================================
    // FORMAT PRICE
    // ================================

    function formatPrice(price) {

        return price.toLocaleString("en-US") + "৳";

    }


    // ================================
    // UPDATE ORDER TOTAL
    // ================================

    function updateOrderTotal() {

        const calculatedSubtotal =
            unitPrice * quantity;


        // Product quantity

        quantityInput.value = quantity;

        summaryQuantity.textContent =
            quantity;


        // Unit price

        summaryUnitPrice.textContent =
            formatPrice(unitPrice);


        // Subtotal

        subtotal.textContent =
            formatPrice(calculatedSubtotal);


        // Total

        total.textContent =
            formatPrice(calculatedSubtotal);

    }


    // ================================
    // PLUS BUTTON
    // ================================

    plusBtn.addEventListener("click", function () {

        quantity++;

        updateOrderTotal();

    });


    // ================================
    // MINUS BUTTON
    // ================================

    minusBtn.addEventListener("click", function () {

        // Don't allow quantity below 1

        if (quantity > 1) {

            quantity--;

            updateOrderTotal();

        }

    });


    // ================================
    // BANGLADESH PHONE VALIDATION
    // ================================

    function validatePhone(phone) {

        /*
         * Bangladesh mobile number:
         *
         * 013XXXXXXXX
         * 014XXXXXXXX
         * 015XXXXXXXX
         * 016XXXXXXXX
         * 017XXXXXXXX
         * 018XXXXXXXX
         * 019XXXXXXXX
         */

        const phoneRegex =
            /^01[3-9]\d{8}$/;

        return phoneRegex.test(phone);

    }


    // ================================
    // CLEAR ERRORS
    // ================================

    function clearErrors() {

        document.getElementById("nameError")
            .textContent = "";

        document.getElementById("phoneError")
            .textContent = "";

        document.getElementById("addressError")
            .textContent = "";


        nameInput.classList.remove("input-error");

        phoneInput.classList.remove("input-error");

        addressInput.classList.remove("input-error");

    }


    // ================================
    // SHOW ERROR
    // ================================

    function showError(
        input,
        errorElement,
        message
    ) {

        input.classList.add("input-error");

        errorElement.textContent =
            message;

    }


    // ================================
    // PLACE ORDER VALIDATION
    // ================================

    placeOrderBtn.addEventListener(
        "click",
        function () {

            clearErrors();


            let isValid = true;


            // ----------------------------
            // NAME
            // ----------------------------

            const name =
                nameInput.value.trim();


            if (name === "") {

                showError(
                    nameInput,
                    document.getElementById(
                        "nameError"
                    ),
                    "আপনার নাম লিখুন।"
                );

                isValid = false;

            }
            else if (name.length < 3) {

                showError(
                    nameInput,
                    document.getElementById(
                        "nameError"
                    ),
                    "সঠিক নাম লিখুন।"
                );

                isValid = false;

            }


            // ----------------------------
            // PHONE
            // ----------------------------

            const phone =
                phoneInput.value.trim();


            if (phone === "") {

                showError(
                    phoneInput,
                    document.getElementById(
                        "phoneError"
                    ),
                    "আপনার ফোন নম্বর লিখুন।"
                );

                isValid = false;

            }
            else if (!validatePhone(phone)) {

                showError(
                    phoneInput,
                    document.getElementById(
                        "phoneError"
                    ),
                    "সঠিক ১১ সংখ্যার মোবাইল নম্বর দিন।"
                );

                isValid = false;

            }


            // ----------------------------
            // ADDRESS
            // ----------------------------

            const address =
                addressInput.value.trim();


            if (address === "") {

                showError(
                    addressInput,
                    document.getElementById(
                        "addressError"
                    ),
                    "আপনার সম্পূর্ণ ঠিকানা লিখুন।"
                );

                isValid = false;

            }
            else if (address.length < 10) {

                showError(
                    addressInput,
                    document.getElementById(
                        "addressError"
                    ),
                    "দয়া করে সম্পূর্ণ ঠিকানা লিখুন।"
                );

                isValid = false;

            }


            // ============================
            // IF VALID
            // ============================

            if (isValid) {

                const orderData = {

                    name: name,

                    phone: phone,

                    address: address,

                    quantity: quantity,

                    unit_price: unitPrice,

                    subtotal:
                        unitPrice * quantity,

                    total:
                        unitPrice * quantity,

                    payment_method: "Cash on Delivery"

                };


                console.log(
                    "Order Data:",
                    orderData
                );


                alert(
                    "আপনার অর্ডার সফলভাবে গ্রহণ করা হয়েছে।"
                );


                /*
                 * এখানে Laravel API call করবেন.
                 *
                 * Example:
                 *
                 * fetch('/order', {
                 *
                 *     method: 'POST',
                 *
                 *     headers: {
                 *         'Content-Type':
                 *             'application/json',
                 *
                 *         'X-CSRF-TOKEN':
                 *             document.querySelector(
                 *                 'meta[name="csrf-token"]'
                 *             ).content
                 *     },
                 *
                 *     body: JSON.stringify(orderData)
                 *
                 * })
                 * .then(response => response.json())
                 * .then(data => {
                 *
                 *     console.log(data);
                 *
                 * });
                 *
                 */

            }

        }
    );


    // ================================
    // PHONE INPUT
    // ONLY NUMBERS
    // ================================

    phoneInput.addEventListener(
        "input",
        function () {

            this.value =
                this.value
                    .replace(/\D/g, "")
                    .slice(0, 11);

        }
    );


    // ================================
    // REMOVE ERROR WHILE TYPING
    // ================================

    nameInput.addEventListener(
        "input",
        function () {

            this.classList.remove(
                "input-error"
            );

            document.getElementById(
                "nameError"
            ).textContent = "";

        }
    );


    phoneInput.addEventListener(
        "input",
        function () {

            this.classList.remove(
                "input-error"
            );

            document.getElementById(
                "phoneError"
            ).textContent = "";

        }
    );


    addressInput.addEventListener(
        "input",
        function () {

            this.classList.remove(
                "input-error"
            );

            document.getElementById(
                "addressError"
            ).textContent = "";

        }
    );


    // Initial calculation

    updateOrderTotal();

});


</script>




