<script>


document.addEventListener("DOMContentLoaded", function () {

    const form = document.getElementById("orderForm");

    if (!form) {
        console.log("Form not found!");
        return;
    }

    const name = document.getElementById("billing_first_name");
    const phone = document.getElementById("billing_phone");
    const address = document.getElementById("billing_address_1");


    // ==============================
    // Create error message elements
    // ==============================

    function createErrorElement(input) {

        let error = document.getElementById(input.id + "_error");

        if (!error) {

            error = document.createElement("div");

            error.id = input.id + "_error";

            error.className = "field-error";

            input.parentNode.appendChild(error);
        }

        return error;
    }


    // ==============================
    // Show error
    // ==============================

    function showError(input, message) {

        const error = createErrorElement(input);

        error.textContent = message;

        input.classList.add("input-error");
    }


    // ==============================
    // Remove error
    // ==============================

    function clearError(input) {

        const error = document.getElementById(
            input.id + "_error"
        );

        if (error) {
            error.textContent = "";
        }

        input.classList.remove("input-error");
    }


    // ==============================
    // Validate name
    // ==============================

    function validateName() {

        const value = name.value.trim();

        if (value === "") {

            showError(
                name,
                "Please enter your name."
            );

            return false;
        }

        if (value.length < 3) {

            showError(
                name,
                "Name must be at least 3 characters."
            );

            return false;
        }

        clearError(name);

        return true;
    }


    // ==============================
    // Validate phone
    // ==============================

    function validatePhone() {

        const value = phone.value.trim();

        if (value === "") {

            showError(
                phone,
                "Please enter your phone number."
            );

            return false;
        }


        // Bangladesh mobile number
        const phonePattern =
            /^01[3-9][0-9]{8}$/;


        if (!phonePattern.test(value)) {

            showError(
                phone,
                "Please enter a valid Bangladesh phone number. Example: 01740154669"
            );

            return false;
        }


        clearError(phone);

        return true;
    }


    // ==============================
    // Validate address
    // ==============================

    function validateAddress() {

        const value = address.value.trim();

        if (value === "") {

            showError(
                address,
                "Please enter your complete address."
            );

            return false;
        }


        if (value.length < 10) {

            showError(
                address,
                "Please enter your complete address."
            );

            return false;
        }


        clearError(address);

        return true;
    }


    // ==============================
    // Form Submit
    // ==============================

    form.addEventListener("submit", function (e) {

        const nameValid = validateName();

        const phoneValid = validatePhone();

        const addressValid = validateAddress();


        if (
            !nameValid ||
            !phoneValid ||
            !addressValid
        ) {

            e.preventDefault();

            // Focus first invalid field
            if (!nameValid) {

                name.focus();

            } else if (!phoneValid) {

                phone.focus();

            } else if (!addressValid) {

                address.focus();

            }

            return false;
        }

        // button hide section
        if (this.dataset.submitted === '1') {

            e.preventDefault();

            return false;
        }

        this.dataset.submitted = '1';

        const button = this.querySelector(
            'button[type="submit"], input[type="submit"]'
        );

        if (button) {

            button.disabled = true;

            button.innerText =
                'অর্ডার প্রসেস হচ্ছে...';
        }


    });




    // ==============================
    // Real-time validation
    // ==============================

    name.addEventListener("input", function () {

        validateName();

    });


    phone.addEventListener("input", function () {

        validatePhone();

    });


    address.addEventListener("input", function () {

        validateAddress();

    });

});
</script>


<script>
(function () {
    function loadYouTubeVideo(wrapper) {
        if (!wrapper || wrapper.dataset.loaded === "1") return;

        var id = wrapper.getAttribute("data-youtube-id");
        if (!id) return;

        wrapper.dataset.loaded = "1";

        var iframe = document.createElement("iframe");
        iframe.src = "https://www.youtube.com/embed/" + encodeURIComponent(id) + "?autoplay=1&rel=0";
        iframe.title = "Oral Care Product Video";
        iframe.loading = "lazy";
        iframe.allow = "accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share";
        iframe.allowFullscreen = true;

        wrapper.textContent = "";
        wrapper.appendChild(iframe);
    }

    document.addEventListener("click", function (event) {
        var wrapper = event.target.closest(".video-lazy");
        if (wrapper) loadYouTubeVideo(wrapper);
    });

    document.addEventListener("keydown", function (event) {
        if (event.key !== "Enter" && event.key !== " ") return;
        var wrapper = event.target.closest(".video-lazy");
        if (!wrapper) return;

        event.preventDefault();
        loadYouTubeVideo(wrapper);
    });
})();
</script>


<script id="mh-image-slider-js">
document.addEventListener('DOMContentLoaded', function () {
    const slider = document.getElementById('mhImageSlider');
    if (!slider) return;
    const track = slider.querySelector('.mh-slider-track');
    const slides = slider.querySelectorAll('.mh-slide');
    const dots = slider.querySelectorAll('.mh-slider-dots button');
    const prev = slider.querySelector('.mh-slider-prev');
    const next = slider.querySelector('.mh-slider-next');
    let index = 0;
    let timer;
    const total = slides.length;
    function goTo(i, restart = true) {
        index = (i + total) % total;
        track.style.transform = 'translate3d(-' + (index * 100) + '%,0,0)';
        slides.forEach((slide, n) => slide.classList.toggle('is-active', n === index));
        dots.forEach((dot, n) => {
            dot.classList.toggle('is-active', n === index);
            dot.setAttribute('aria-selected', n === index ? 'true' : 'false');
        });
        if (restart) startAuto();
    }
    function startAuto() {
        clearInterval(timer);
        timer = setInterval(() => goTo(index + 1, false), 3000);
    }
    prev.addEventListener('click', () => goTo(index - 1));
    next.addEventListener('click', () => goTo(index + 1));
    dots.forEach((dot, n) => dot.addEventListener('click', () => goTo(n)));
    slider.addEventListener('mouseenter', () => clearInterval(timer));
    slider.addEventListener('mouseleave', startAuto);
    slider.addEventListener('touchstart', () => clearInterval(timer), {passive:true});
    slider.addEventListener('touchend', startAuto, {passive:true});
    startAuto();
});
</script>

